import{c as a,Q as t,j as l,m as n}from"./chunks/framework.g_l1frA7.js";const m=JSON.parse('{"title":"Debt Snowball","description":"","frontmatter":{},"headers":[],"relativePath":"framework/debt-snowball.md","filePath":"framework/debt-snowball.md","lastUpdated":null}'),s={name:"framework/debt-snowball.md"};function o(r,e,i,d,h,b){return t(),l("div",null,[...e[0]||(e[0]=[n('<h1 id="debt-snowball" tabindex="-1">Debt Snowball <a class="header-anchor" href="#debt-snowball" aria-label="Permalink to &quot;Debt Snowball&quot;">​</a></h1><blockquote><p>Pay the smallest balance first, for momentum. — <em>Ramsey</em></p></blockquote><h2 id="how-finsight-orders-debt" tabindex="-1">How FinSight orders debt <a class="header-anchor" href="#how-finsight-orders-debt" aria-label="Permalink to &quot;How FinSight orders debt&quot;">​</a></h2><p><code>wellness_context.debt_snowball</code> lists liabilities ordered by <strong>remaining balance ascending</strong>, smallest first. The order is deterministic from the ledger — no LLM ranking.</p><ul><li>Each debt entry shows name, remaining, and rate (when known).</li><li>The smallest is surfaced as “pay this first” in Today’s next-action when debt exists.</li></ul><h2 id="snowball-vs-avalanche" tabindex="-1">Snowball vs avalanche <a class="header-anchor" href="#snowball-vs-avalanche" aria-label="Permalink to &quot;Snowball vs avalanche&quot;">​</a></h2><p>Avalanche (highest rate first) is mathematically cheaper; snowball is behaviourally more robust. FinSight implements snowball as the default order and explains the trade-off when asked. If you prefer avalanche, order debts by rate mentally — the ledger supports either.</p><h2 id="using-it" tabindex="-1">Using it <a class="header-anchor" href="#using-it" aria-label="Permalink to &quot;Using it&quot;">​</a></h2><ul><li><strong>Journey → Debt free</strong> — tracks non-mortgage debt cleared against the snowball.</li><li><strong>Scenarios</strong> — “What if I add $300/month to the smallest debt while holding the others at minimums?” projects payoff date under your actual balances.</li><li><strong>Copilot</strong> — “Which debt should I pay first?” returns the snowball with balances and a plain explanation.</li></ul><p>Clearing a debt removes it from the snowball; the next-smallest becomes the focus automatically.</p>',10)])])}const u=a(s,[["render",o]]);export{m as __pageData,u as default};
